partial class Studio {
 public void TestVersion23(){foreach(int count in new[]{91,110,140}){var arc=EllipseSamples(100,55,.7,true).GetRange(0,count);var fit=FittedEllipse.Fit(arc);if(fit==null||StrokeSession.Distance(fit.Centre,new PointF(300,250))>12)throw new Exception("Open ellipse recognition");}SetDocument(new Document("A4",100),null);canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.TestSelectionCombinations();canvas.ClearSelection();selectionMode.SelectedItem="Draw";using(var g=Graphics.FromImage(canvas.Doc.Selected.Image)){g.Clear(Color.Transparent);using(var pen=new Pen(Color.Black,8))g.DrawRectangle(pen,40,40,140,140);}canvas.Ink=Color.Orange;canvas.Focus();var msg=new Message();ProcessCmdKey(ref msg,Keys.F);if(!canvas.FillTool||canvas.Ink!=Color.Orange)throw new Exception("Bucket shortcut/colour");int history=undo.Count;canvas.TestDrag(new Point(100,100),new Point(100,100));if(undo.Count!=history+1||canvas.Doc.Selected.Image.GetPixel(100,100).ToArgb()!=Color.Orange.ToArgb()||canvas.Doc.Selected.Image.GetPixel(20,20).A!=0)throw new Exception("Bounded fill");Travel(undo,redo);if(canvas.Doc.Selected.Image.GetPixel(100,100).A!=0)throw new Exception("Fill undo");Travel(redo,undo);history=undo.Count;canvas.FillAt(new PointF(100,100));if(undo.Count!=history)throw new Exception("No-op fill history");canvas.TestBoxOperation(new Point(60,60),new Point(120,120),0);canvas.SetSelectionMode("Draw");canvas.Ink=Color.Blue;canvas.FillAt(new PointF(80,80));if(canvas.Doc.Selected.Image.GetPixel(80,80).ToArgb()!=Color.Blue.ToArgb()||canvas.Doc.Selected.Image.GetPixel(140,140).ToArgb()!=Color.Orange.ToArgb())throw new Exception("Selection-clipped fill");canvas.ClearSelection();canvas.FillAt(new PointF(10,10));if(canvas.Doc.Selected.Image.GetPixel(10,10).ToArgb()!=Color.Blue.ToArgb()||canvas.Doc.Selected.Image.GetPixel(140,140).ToArgb()!=Color.Orange.ToArgb())throw new Exception("Transparent background fill boundary");SelectTool("Pen");if(canvas.FillTool)throw new Exception("Leave bucket tool");dirty=false;}
 Button fillBucketButton,pageFillButton;
 void AddFillButton(FlowLayoutPanel tools){fillBucketButton=Theme.Button("Visible fill   K",delegate{SelectFillBucket();});fillBucketButton.Width=170;fillBucketButton.Height=32;var icon=new Bitmap(24,24);using(var g=Graphics.FromImage(icon)){g.SmoothingMode=SmoothingMode.AntiAlias;Point[] points={new Point(10,3),new Point(21,14),new Point(12,21),new Point(2,11)};g.FillPolygon(Brushes.LightSteelBlue,points);g.DrawPolygon(Pens.SlateGray,points);g.DrawArc(Pens.SlateGray,7,1,9,9,180,180);g.FillEllipse(Brushes.Teal,19,17,4,6);}fillBucketButton.Image=icon;fillBucketButton.ImageAlign=ContentAlignment.MiddleLeft;fillBucketButton.TextAlign=ContentAlignment.MiddleRight;tools.Controls.Add(fillBucketButton);pageFillButton=Theme.Button("Fill   F",delegate{canvas.EndStroke();canvas.FillSelectionColour();canvas.Focus();});pageFillButton.Image=(Bitmap)icon.Clone();pageFillButton.ImageAlign=ContentAlignment.MiddleLeft;pageFillButton.Width=170;pageFillButton.Height=32;tools.Controls.Add(pageFillButton);int index=tools.Controls.GetChildIndex(toolButtons["Paintbrush"])+1;tools.Controls.SetChildIndex(pageFillButton,index);tools.Controls.SetChildIndex(fillBucketButton,index+1);}
 void SelectFillBucket(){if(canvas.Doc==null||!canvas.Doc.Selected.IsRaster)return;canvas.EndStroke();canvas.SetSelectionMode("Draw");selectionMode.SelectedItem="Draw";guideMode.SelectedItem="Freehand";canvas.FillTool=true;foreach(var b in toolButtons.Values){b.BackColor=Theme.Panel;b.ForeColor=Theme.Text;}fillBucketButton.BackColor=Theme.Accent;canvas.Focus();canvas.RefreshCursor();UpdateStatus();}
}
partial class Canvas {
 public void TestBoxOperation(Point a,Point b,int operation){SetSelectionMode("Box selection");OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,a.X,a.Y,0));selectionOperation=operation;OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,b.X,b.Y,0));}
 public void TestSelectionCombinations(){ClearSelection();TestBoxOperation(new Point(20,20),new Point(100,100),0);TestBoxOperation(new Point(80,20),new Point(160,100),1);if(SelectionMask[50*Doc.Width+30]==0||SelectionMask[50*Doc.Width+140]==0||SelectionMask[50*Doc.Width+180]!=0)throw new Exception("Add selection");TestBoxOperation(new Point(60,40),new Point(120,80),-1);if(SelectionMask[50*Doc.Width+90]!=0||SelectionMask[30*Doc.Width+90]==0||SelectionMask[50*Doc.Width+30]==0)throw new Exception("Subtract selection hole");TestDraftPaint();TestBoxOperation(new Point(0,0),new Point(200,200),-1);if(Array.Exists(SelectionMask,p=>p!=0))throw new Exception("Subtract entire selection");TestDraftPaint();ClearSelection();SetSelectionMode("Lasso selection");OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,20,50,0));for(int x=21;x<100;x++)OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,x,x%2==0?45:55,0));double error=0;int n=0;foreach(var p in selectionPoints)if(p.X>40){error+=Math.Abs(p.Y-50);n++;}if(n==0||error/n>=3)throw new Exception("Lasso 50% jitter smoothing");CancelSelectionDraft();SetSelectionMode("Draw");}
 public bool FillTool;
 public void FillAt(PointF p){if(Doc==null||!Doc.Selected.IsRaster||Doc.Selected.IsLocked||!Doc.Selected.Visible)return;int w=Doc.Width,h=Doc.Height,x=(int)Math.Floor(p.X),y=(int)Math.Floor(p.Y);if(x<0||y<0||x>=w||y>=h)return;int seed=y*w+x;if(SelectionMask!=null&&SelectionMask[seed]==0)return;var image=Doc.Selected.Image;int[] pixels=new int[w*h];var data=image.LockBits(new Rectangle(0,0,w,h),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{for(int row=0;row<h;row++)Marshal.Copy(IntPtr.Add(data.Scan0,row*data.Stride),pixels,row*w,w);}finally{image.UnlockBits(data);}int original=pixels[seed],colour=Color.FromArgb(Ink.R,Ink.G,Ink.B).ToArgb();if(original==colour)return;bool transparent=(original&unchecked((int)0xff000000))==0;Func<int,bool> matches=delegate(int i){return (SelectionMask==null||SelectionMask[i]!=0)&&(transparent?(pixels[i]&unchecked((int)0xff000000))==0:pixels[i]==original);};if(BeforeStroke!=null)BeforeStroke();var stack=new Stack<int>();stack.Push(seed);while(stack.Count>0){int point=stack.Pop();if(!matches(point))continue;int row=point/w,left=point%w,right=left;while(left>0&&matches(row*w+left-1))left--;while(right+1<w&&matches(row*w+right+1))right++;for(int xx=left;xx<=right;xx++)pixels[row*w+xx]=colour;for(int side=-1;side<=1;side+=2){int yy=row+side;if(yy<0||yy>=h)continue;bool run=false;for(int xx=left;xx<=right;xx++){bool hit=matches(yy*w+xx);if(hit&&!run)stack.Push(yy*w+xx);run=hit;}}}data=image.LockBits(new Rectangle(0,0,w,h),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{for(int row=0;row<h;row++)Marshal.Copy(pixels,row*w,IntPtr.Add(data.Scan0,row*data.Stride),w);}finally{image.UnlockBits(data);}if(AfterStroke!=null)AfterStroke();Invalidate();}
 void BuildSelectionOutline(){if(selectionPath!=null)selectionPath.Dispose();selectionPath=new GraphicsPath();int w=Doc.Width,h=Doc.Height;for(int y=0;y<=h;y++){int start=-1;for(int x=0;x<=w;x++){bool edge=x<w&&((y>0&&SelectionMask[(y-1)*w+x]!=0)!=(y<h&&SelectionMask[y*w+x]!=0));if(edge&&start<0)start=x;if(!edge&&start>=0){selectionPath.StartFigure();selectionPath.AddLine(start,y,x,y);start=-1;}}}for(int x=0;x<=w;x++){int start=-1;for(int y=0;y<=h;y++){bool edge=y<h&&((x>0&&SelectionMask[y*w+x-1]!=0)!=(x<w&&SelectionMask[y*w+x]!=0));if(edge&&start<0)start=y;if(!edge&&start>=0){selectionPath.StartFigure();selectionPath.AddLine(x,start,x,y);start=-1;}}}}
}
